       .support-copy {
         border-right: 0;
         border-bottom: 1px solid rgba(148, 163, 184, 0.12);
       }

       .support-copy,
       .support-form-wrap {
         padding: 24px;
       }
     }
   </style>
 </head>
 <body>
   <div id="app"></div>
   <script>
     const fieldConfig = {
       fullName: {
         id: "full-name",
         label: "Full name",
         type: "text",
         placeholder: "Alex Morgan",
         required: true,
         autoComplete: "name",
         helperText: "",
         validate(value) {
           return value.trim() ? "" : "Please enter your full name.";
         }
       },
       email: {
         id: "email-address",
         label: "Email address",
         type: "email",
         placeholder: "alex@example.com",
         required: true,
         autoComplete: "email",
         helperText: "",
         validate(value) {
           if (!value.trim()) {
             return "Please enter your email address.";
           }

           return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)
             ? ""
             : "Enter a valid email address.";
         }
       },
       phone: {
         id: "phone-number",
         label: "Phone number",
         type: "tel",
         placeholder: "(555) 123-4567",
         required: false,
         autoComplete: "tel",
         helperText: "Use digits with an optional country code, for example +1 555 123 4567.",
         validate(value) {
           if (!value.trim()) {
             return "";
           }

           return /^[+\d\s().-]{7,20}$/.test(value)
             ? ""
             : "Use a valid phone number format.";
         }
       }
     };

     function FormField(config) {
       const requiredIndicator = config.required
         ? '<span class="required-indicator" aria-hidden="true">*</span>'
         : "";
       const helperMarkup = config.helperText
         ? '<p class="field-note" id="' + config.id + '-note">' + config.helperText + "</p>"
         : "";

       return (
         '<div class="form-field">' +
           '<label for="' + config.id + '">' + config.label + " " + requiredIndicator + "</label>" +
           '<input' +
             ' id="' + config.id + '"' +
             ' name="' + config.id + '"' +
             ' type="' + config.type + '"' +
             ' placeholder="' + config.placeholder + '"' +
             ' autocomplete="' + config.autoComplete + '"' +
             (config.required ? " required" : "") +
             ' aria-describedby="' + [config.helperText ? config.id + "-note" : "", config.id + "-error"].filter(Boolean).join(" ") + '"' +
           ">" +
           helperMarkup +
           '<p class="error-message" id="' + config.id + '-error" aria-live="polite"></p>' +
         "</div>"
       );
     }

     function ContactForm() {
       return (
         '<div class="page-shell">' +
           '<section class="support-card" aria-labelledby="support-heading">' +
             '<div class="support-layout">' +
               '<div class="support-copy">' +
                 '<span class="eyebrow">Support Team</span>' +
                 '<h1 id="support-heading">Tell us how we can help.</h1>' +
                 '<p>Send your details and a support specialist will follow up with the right next step for your request.</p>' +
               "</div>" +
               '<div class="support-form-wrap">' +
                 '<p class="helper-text">Required fields are marked with an asterisk.</p>' +
                 '<form id="support-form" novalidate>' +
                   FormField(fieldConfig.fullName) +
                   FormField(fieldConfig.email) +
                   FormField(fieldConfig.phone) +
                   '<button type="submit">Submit request</button>' +
                 "</form>" +
               "</div>" +
             "</div>" +
           "</section>" +
         "</div>"
       );
     }

     document.getElementById("app").innerHTML = ContactForm();

     const form = document.getElementById("support-form");
     const inputs = Array.from(form.querySelectorAll("input"));

     function showError(input, message) {
       const error = document.getElementById(input.id + "-error");
       input.classList.toggle("input-invalid", Boolean(message));
       input.setAttribute("aria-invalid", message ? "true" : "false");
       error.textContent = message;
     }

     function validateInput(input) {
       const config = Object.values(fieldConfig).find((field) => field.id === input.id);
       const message = config.validate(input.value);
       showError(input, message);
       return !message;
     }

     inputs.forEach((input) => {
       input.addEventListener("blur", () => {
         validateInput(input);
       });

       input.addEventListener("input", () => {
         const error = document.getElementById(input.id + "-error");
         if (error.textContent) {
           validateInput(input);
         }
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const isValid = inputs.map(validateInput).every(Boolean);
       if (isValid) {
         form.reset();
         inputs.forEach((input) => showError(input, ""));
       }
     });
   </script>
 </body>
 </html>

')
